package com.productionhouse.crm.legal.contracts.dto;
import jakarta.validation.constraints.*;import java.time.LocalDate;
public record ContractRequest(@NotBlank @Size(max=200) String name,@Size(max=2000) String description,@Size(max=120) String projectRef,@NotBlank @Size(max=80) String contractType,@NotBlank @Size(max=200) String partyOne,@Size(max=200) String partyTwo,@Positive Long mediaId,@NotBlank @Size(max=40) String status,@NotNull LocalDate startsAt,LocalDate endsAt,LocalDate renewalAt,@Size(max=500) String documentReference,@Size(max=2000) String notes,Boolean active,@jakarta.validation.constraints.PositiveOrZero @Digits(integer=17,fraction=2) java.math.BigDecimal contractValue,@Size(max=200) String governingLaw){
public ContractRequest(String name,String description,String projectRef,String contractType,String partyOne,String partyTwo,Long mediaId,String status,LocalDate startsAt,LocalDate endsAt,LocalDate renewalAt,String documentReference,String notes,Boolean active){this(name,description,projectRef,contractType,partyOne,partyTwo,mediaId,status,startsAt,endsAt,renewalAt,documentReference,notes,active,null,null);}
}
